import{_ as a,o as e,c as s,a2 as d}from"./chunks/framework.CCCdsIgc.js";const n="/help/terminal-banner.png",g=JSON.parse('{"title":"终端对话","description":"","frontmatter":{},"headers":[],"relativePath":"guide/terminal.md","filePath":"guide/terminal.md"}'),i={name:"guide/terminal.md"};function o(l,t,p,r,c,h){return e(),s("div",null,[...t[0]||(t[0]=[d(`<h1 id="终端对话" tabindex="-1">终端对话 <a class="header-anchor" href="#终端对话" aria-label="Permalink to &quot;终端对话&quot;">​</a></h1><p>不打开聊天窗口，直接在 <strong>cmd、PowerShell 或 Windows Terminal</strong> 里和 FlyknitBuddy 一句一句地聊，让它在当前文件夹里读文件、跑命令、改代码。体验类似 Codex CLI、Claude Code。</p><p>用的是这台电脑上 FlyknitBuddy 的登录，权限、确认、额度、审计和聊天窗口完全一样。</p><h2 id="开始之前" tabindex="-1">开始之前 <a class="header-anchor" href="#开始之前" aria-label="Permalink to &quot;开始之前&quot;">​</a></h2><table tabindex="0"><thead><tr><th>要求</th><th>怎么确认</th></tr></thead><tbody><tr><td>IT 打开了「命令行 / IDE 接入」</td><td>没开时运行 <code>flyknit</code> 会提示「IT 没有开启命令行 / IDE 接入」，找 IT 在安全中心打开</td></tr><tr><td>这台电脑登录过 FlyknitBuddy</td><td>打开桌面端登录一次即可，命令行用同一个登录</td></tr><tr><td>装的是新版</td><td>输入 <code>flyknit --help</code>，第一行是「flyknit　在命令行里和 FlyknitBuddy 对话」就是新版</td></tr></tbody></table><p><code>flyknit.exe</code> 和 FlyknitBuddy 装在一起（默认 <code>C:\\Program Files\\FlyknitBuddy</code>），安装时已经加进 PATH，<strong>新开</strong>一个命令行窗口就能用。</p><div class="tip custom-block"><p class="custom-block-title">推荐用 Windows Terminal</p><p>Win11 自带，开始菜单搜「终端」。颜色、中文、表格显示效果最好。cmd 和 PowerShell 也都能用。</p></div><h2 id="第一次对话" tabindex="-1">第一次对话 <a class="header-anchor" href="#第一次对话" aria-label="Permalink to &quot;第一次对话&quot;">​</a></h2><p><strong>1. 打开命令行，进入要处理的文件夹</strong></p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-6bRyb" id="tab-cpZNT6e" checked><label data-title="cmd" for="tab-cpZNT6e">cmd</label><input type="radio" name="group-6bRyb" id="tab-tCTJhYK"><label data-title="PowerShell" for="tab-tCTJhYK">PowerShell</label></div><div class="blocks"><div class="language-bat vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">cd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /d D:\\工作\\日报</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flyknit</span></span></code></pre></div><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cd D:\\工作\\日报</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flyknit</span></span></code></pre></div></div></div><p><code>cd /d</code> 在 cmd 里可以连盘符一起切换。进入的文件夹就是这次对话的<strong>工作区</strong>：AI 默认只在这里面读写，生成的文件也放在这里。</p><p><strong>2. 看到欢迎画面后直接打字，回车发送</strong></p><p><img src="`+n+`" alt="flyknit 欢迎画面"></p><p>终端窗口不够宽（不到约 100 列）时，大字会换成一行小字；把输出重定向到文件时只输出文字信息。</p><p><strong>3. 看它干活</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  ▸ 列出目录 .</span></span>
<span class="line"><span>    ✓ 共 31 个文件</span></span>
<span class="line"><span>  ▸ 读取 10-01.xlsx</span></span>
<span class="line"><span>    ✓ Sheet1：42 行</span></span>
<span class="line"><span>  … 思考中</span></span>
<span class="line"><span>  ▸ 执行 python merge.py</span></span>
<span class="line"><span>  ⚠ 需要确认：执行 python merge.py</span></span>
<span class="line"><span>    理由：用脚本把 31 个文件合并成一张表</span></span>
<span class="line"><span>    [y] 允许一次  [a] 以后自动  [n] 拒绝 &gt; y</span></span>
<span class="line"><span>    已允许这一次</span></span>
<span class="line"><span>    ✓ 已生成 10月汇总.xlsx</span></span>
<span class="line"><span>汇总好了，放在 D:\\工作\\日报\\10月汇总.xlsx，共 31 天、1302 行……</span></span>
<span class="line"><span>· 3 次工具 · 18.4k tokens · 42.1 秒</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&gt;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>看到的</th><th>意思</th></tr></thead><tbody><tr><td><code>▸ …</code></td><td>开始一步操作（读文件、跑命令、改文件……）</td></tr><tr><td><code>✓</code> / <code>✗</code></td><td>这一步成功 / 失败，后面是结果的第一行</td></tr><tr><td><code>… 思考中</code></td><td>在等 AI 回复，第一个字出来就会消失</td></tr><tr><td><code>· 3 次工具 · 18.4k tokens · 42.1 秒</code></td><td>这一轮结束：用了几次工具、多少 token、多久；没做完时会写原因</td></tr></tbody></table><p><strong>4. 接着说下一句</strong>，它记得前面聊过的内容。说完了输入 <code>/exit</code> 退出。</p><h2 id="需要确认的操作" tabindex="-1">需要确认的操作 <a class="header-anchor" href="#需要确认的操作" aria-label="Permalink to &quot;需要确认的操作&quot;">​</a></h2><p>和聊天窗口里的确认卡片一样，只是改成在命令行里问：</p><table tabindex="0"><thead><tr><th>输入</th><th>效果</th></tr></thead><tbody><tr><td><code>y</code></td><td>允许这一次</td></tr><tr><td><code>a</code></td><td>允许，并且<strong>以后同类操作自动执行</strong>（和 FlyknitBuddy 里的「以后自动」是同一套规则，可以在 FlyknitBuddy「设置 → 自动执行规则」里撤销）</td></tr><tr><td><code>n</code> 或直接回车</td><td>拒绝，AI 会换别的办法或者问你</td></tr></tbody></table><ul><li>删除、覆盖、改系统设置这类<strong>高危操作只有 <code>y</code> / <code>n</code></strong>，输入 <code>a</code> 会再问一次。</li><li>查目录、看文件这类只读操作不问，直接做。</li><li>命令行里没有「完全权限」，最多是「工作区内修改」。</li></ul><h2 id="命令" tabindex="-1">命令 <a class="header-anchor" href="#命令" aria-label="Permalink to &quot;命令&quot;">​</a></h2><p>在 <code>&gt;</code> 后面输入：</p><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/help</code></td><td>显示命令说明</td></tr><tr><td><code>/new</code></td><td>开一个新对话（当前的已经保存）</td></tr><tr><td><code>/resume</code></td><td>列出这个文件夹里以前的对话，输入序号打开接着聊</td></tr><tr><td><code>/resume 2</code></td><td>直接打开列表里的第 2 个</td></tr><tr><td><code>/plan</code></td><td>看当前的任务计划</td></tr><tr><td><code>/usage</code></td><td>这个对话用了多少 token（和聊天窗口共用今日额度）</td></tr><tr><td><code>/compact</code></td><td>马上整理对话：较早的压成摘要，省 token；后面可以写要重点保留的，如 <code>/compact 保留报价和交期</code></td></tr><tr><td><code>/context</code></td><td>上下文用了多少、系统提示 / 工具 / 对话各占多少</td></tr><tr><td><code>/permission 只读</code></td><td>调权限：<code>只读</code> 或 <code>工作区</code>；不带参数看当前是哪一档。命令行没有完全权限</td></tr><tr><td><code>/think</code></td><td>打开 / 关闭深度思考（也可以写 <code>/think 开</code>、<code>/think 关</code>）；打开后会显示思考过程</td></tr><tr><td><code>/status</code></td><td>版本、会话、工作区、权限、开发者工具、深度思考一览</td></tr><tr><td><code>/clear</code></td><td>清屏</td></tr><tr><td><code>/exit</code></td><td>退出</td></tr></tbody></table><p>打 <code>/</code> 和命令的头几个字母，按 <strong>Tab</strong> 自动补全（比如 <code>/pl</code> + Tab → <code>/plan</code>、<code>/th</code> + Tab → <code>/think</code>）；对得上的有好几个时（比如 <code>/p</code> 既可能是 <code>/plan</code> 也可能是 <code>/permission</code>），再按一次 Tab 把它们列出来。</p><h2 id="输入时的按键" tabindex="-1">输入时的按键 <a class="header-anchor" href="#输入时的按键" aria-label="Permalink to &quot;输入时的按键&quot;">​</a></h2><table tabindex="0"><thead><tr><th>按键</th><th>作用</th></tr></thead><tbody><tr><td>退格</td><td>删掉最后一个字</td></tr><tr><td>Esc</td><td>清空这一行</td></tr><tr><td>Tab</td><td>补全命令</td></tr><tr><td>↑ / ↓</td><td>翻之前输过的话</td></tr></tbody></table><h2 id="输入多行" tabindex="-1">输入多行 <a class="header-anchor" href="#输入多行" aria-label="Permalink to &quot;输入多行&quot;">​</a></h2><ul><li><strong>行尾加 <code>\\</code></strong> 回车，接着写下一行。</li><li><strong>粘贴大段文字</strong>：先单独输入一行 <code>&quot;&quot;&quot;</code> 回车，粘贴，再输入一行 <code>&quot;&quot;&quot;</code> 回车。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&gt; &quot;&quot;&quot;</span></span>
<span class="line"><span>… 帮我把下面这段需求整理成任务清单：</span></span>
<span class="line"><span>… 1. 每天 8 点汇总各车间日报</span></span>
<span class="line"><span>… 2. 缺勤超过 3 人的车间标红</span></span>
<span class="line"><span>… &quot;&quot;&quot;</span></span></code></pre></div><h2 id="停下和退出" tabindex="-1">停下和退出 <a class="header-anchor" href="#停下和退出" aria-label="Permalink to &quot;停下和退出&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>效果</th></tr></thead><tbody><tr><td>任务进行中按 <strong>Ctrl+C</strong></td><td>只停下这一轮（已经开始的操作照常收尾），回到 <code>&gt;</code> 继续聊</td></tr><tr><td>空闲时按 Ctrl+C</td><td>提示「再按一次退出」；两秒内再按一次才退出</td></tr><tr><td>输入 <code>/exit</code></td><td>退出</td></tr></tbody></table><p>对话每一轮结束都会自动保存，直接关掉窗口也不会丢。</p><h2 id="接着以前的对话" tabindex="-1">接着以前的对话 <a class="header-anchor" href="#接着以前的对话" aria-label="Permalink to &quot;接着以前的对话&quot;">​</a></h2><div class="language-bat vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flyknit -c              :: 接着这个文件夹里最近的一次对话</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flyknit --resume        :: 列出以前的对话，选一个接着聊</span></span></code></pre></div><p>打开后会显示上次最后一问一答，提醒你聊到哪了。</p><p>命令行和 <a href="/help/guide/ide.html">IDE</a> 里的对话存在同一个地方（这台电脑上，最多 50 个、保留 30 天，不上传），<strong>在 VS Code 里聊了一半，可以回到命令行里接着聊</strong>，反过来也一样。</p><h2 id="常用参数" tabindex="-1">常用参数 <a class="header-anchor" href="#常用参数" aria-label="Permalink to &quot;常用参数&quot;">​</a></h2><div class="language-bat vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flyknit </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;看看这个项目是做什么的&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        :: 带着第一句话进入</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flyknit -w D:\\repo                     :: 指定工作区，不用先 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">cd</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flyknit --permission readonly          :: 只读：只能看，不能改</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flyknit --think                        :: 让 AI 每一步先深度思考（更慢、更费额度）</span></span></code></pre></div><p>深度思考默认<strong>关</strong>，不跟聊天窗口里的「深度思考」开关走：命令行里的任务常常要十几、几十步，每步都先想一大段会慢很多。真遇到难题再加 <code>--think</code>。</p><h2 id="用法举例" tabindex="-1">用法举例 <a class="header-anchor" href="#用法举例" aria-label="Permalink to &quot;用法举例&quot;">​</a></h2><table tabindex="0"><thead><tr><th>想做的事</th><th>可以这样说</th></tr></thead><tbody><tr><td>整理文件夹</td><td>「把这里的文件按月份分到不同文件夹，先列出计划给我看」</td></tr><tr><td>汇总表格</td><td>「把所有 xlsx 的第一个工作表合成一张，按日期排序」</td></tr><tr><td>看懂一个项目</td><td>「这个项目是做什么的？目录结构和主要模块讲一下」</td></tr><tr><td>改代码</td><td>「把 utils.py 里的两个 TODO 修掉，改完跑一下测试」</td></tr><tr><td>查问题</td><td>「运行 npm test，失败的话找出原因并修好」</td></tr></tbody></table><p>改代码、用 git、建 PR 需要 IT 打开「开发者工具」，见 <a href="/help/guide/developer.html">开发者工具与 PR</a>。</p><h2 id="一次性任务-flyknit-p" tabindex="-1">一次性任务（flyknit -p） <a class="header-anchor" href="#一次性任务-flyknit-p" aria-label="Permalink to &quot;一次性任务（flyknit -p）&quot;">​</a></h2><p>只想跑一次、拿到结果就结束（比如放进脚本或计划任务）时用 <code>-p</code>：</p><div class="language-bat vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flyknit -p </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;把 docs 目录里的 md 文件列出来&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> --format text</span></span></code></pre></div><p>在命令行里直接运行时会边做边显示进度，最后输出结果。<code>-p</code> 没有人可以问，<strong>需要确认的操作默认一律拒绝</strong>，结束时会列出被拒绝的操作；要执行脚本、访问网络这类需要你点头的事，去掉 <code>-p</code> 用对话模式。详见 <a href="/help/guide/cli-and-ide.html">命令行脚本与 CI</a>。</p><h2 id="遇到问题" tabindex="-1">遇到问题 <a class="header-anchor" href="#遇到问题" aria-label="Permalink to &quot;遇到问题&quot;">​</a></h2><p><strong>提示「&#39;flyknit&#39; 不是内部或外部命令」</strong></p><p>PATH 只对新开的窗口生效，关掉重开一个命令行。还不行就用完整路径：</p><div class="language-bat vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;C:\\Program Files\\FlyknitBuddy\\flyknit.exe&quot;</span></span></code></pre></div><p><strong>输入 <code>flyknit</code> 只显示帮助，不进入对话</strong></p><p>用的是旧版本。可以先看看实际用的是哪一个：</p><div class="language-bat vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">where</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> flyknit</span></span></code></pre></div><p>列出多个时，排在第一个的会被使用。升级 FlyknitBuddy 到最新版，或者用完整路径运行新版。</p><p><strong><code>flyknit -p</code> 半天没反应</strong></p><p>旧版 <code>-p</code> 要等整个任务做完才输出。升级到新版会边做边显示进度；需要来回确认的事情改用 <code>flyknit</code> 对话。</p><p><strong>打的字删不掉、Tab 不补全</strong></p><p>升级到最新版。旧版输入行交给系统处理，第一个字退格删不掉，也没有 Tab 补全。</p><p><strong>中文是乱码、颜色是一堆奇怪的符号</strong></p><p>升级到最新版。新版对话时会自动切换到 UTF-8，并在老的 cmd 窗口里打开颜色支持。还有问题就换 Windows Terminal。</p><p><strong>提示「还没登录 FlyknitBuddy」</strong></p><p>打开桌面端 FlyknitBuddy 登录一次。登录过期了也一样，重新登录即可。</p><p><strong>提示「IT 没有开启命令行 / IDE 接入」</strong></p><p>找 IT 在管理后台「安全中心」（或你所在部门的安全设置）里打开。</p><p><strong>提示今天的额度用完了</strong></p><p>命令行和聊天窗口共用每天的额度，第二天自动恢复，急用找 IT 调整。</p>`,68)])])}const b=a(i,[["render",o]]);export{g as __pageData,b as default};
